INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 17, 'theory', 'Quiz: RISC-V in practice');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 0, 'Which register holds the system call number in Linux on RISC-V?', '["a0", "a7", "ra", "sp"]', 1, 'The call number goes in a7, the arguments in a0, a1, a2 and so on; then you execute ecall. write is 64, exit is 93.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 1, 'What does write(1, buf, 15) do?', '["Reads 15 bytes from the keyboard", "Ends the program with code 15", "Allocates 15 bytes of memory", "Prints 15 bytes from buf to standard output"]', 3, 'The first argument is the file number (1 = stdout), the second is the buffer address, the third is the number of bytes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 2, 'Why does print_uint fill the buffer from right to left?', '["It makes ecall run faster", "Linux requires it", "Digits come out from least to most significant: first the remainder of division by 10", "To avoid using the stack"]', 2, 'The remainder of division by 10 is the last digit. The least significant digit comes out first, so it goes at the end of the buffer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 3, 'What is the program''s exit code after exit(300), if the shell shows it with echo $?', '["300", "44", "0", "255"]', 1, 'The exit code is a single byte: 300 mod 256 = 44.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 17, 4, 'What does llvm-objdump -d show?', '["The program''s source text", "Variable contents while it runs", "A list of installed libraries", "The real machine words and instructions from the built file"]', 3, 'The disassembler turns machine words into instructions, which is handy for checking against the trainer''s listing.');
